@Component({
  template: `
    @for (u of sortedUsers(); track u.id) {
      <li>{{ u.name }}</li>
    }
  `,
})
export class UserList {
  users = input.required<User[]>();

  sortedUsers() {
    return [...this.users()].sort((a, b) => a.name.localeCompare(b.name));
  }
}

